param([Parameter(Mandatory=$true)][string]$RepoRoot)
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";function Die([string]$Code,[string]$Detail){throw($Code+":"+$Detail)};$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path;. (Join-Path $RepoRoot "scripts\storage\_lib_ld_receipts_v1.ps1");$script=Join-Path $RepoRoot "scripts\storage\ld_storage03_resume_idempotency_v1.ps1";$out=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $script -RepoRoot $RepoRoot;if($LASTEXITCODE-ne0){Die "RESUME_FIXTURE_EXIT" ([string]$LASTEXITCODE)};$r=LDREC-ReadReceiptFromOutput $out "ld.device.storage03_resume_idempotency.receipt.v1" (Join-Path $RepoRoot "schemas");if(-not[bool]$r.ok){Die "RESUME_FIXTURE_NOT_OK" ""};if([int]$r.durable_prefix_duplicate_count-ne2){Die "PREFIX_DUPLICATES" ""};if([int]$r.durable_prefix_copied_count-ne2){Die "PREFIX_COPIED" ""};if(-not[bool]$r.stale_partial_blocked){Die "STALE_NOT_BLOCKED" ""};if(-not[bool]$r.operator_cleared_partial_for_recovery){Die "RECOVERY_NOT_EXPLICIT" ""};if([int]$r.repeat_duplicate_count-ne4-or[int]$r.repeat_copied_count-ne0){Die "REPEAT_NOT_IDEMPOTENT" ""};Write-Output "PASS: durable promoted prefix resumes with verified duplicates and remaining files";Write-Output "PASS: stale partials fail closed until an explicit operator cleanup";Write-Output "PASS: recovered and repeated runs are idempotent with unchanged source";Write-Output "SELFTEST_LD_STORAGE03_RESUME_IDEMPOTENCY_OK"
